#!/usr/bin/env python3
from pathlib import Path
import argparse,json,sys
ROOT=Path(__file__).resolve().parents[1]
REGISTRY=ROOT/'content-pools/registry.json'
DOC=ROOT/'docs/architecture/content-architecture.md'
def render():
 r=json.loads(REGISTRY.read_text(encoding='utf-8')); pools=r.get('pools',{}); c=r.get('canonicalContract',{})
 lines=['# NET Psychology — Content Architecture','', '<!-- GENERATED BY scripts/sync_documentation.py. Edit the generator/registry, not this block. -->','',f"**Registry version:** `{r.get('version','unknown')}`",f"**Canonical taxonomy:** `{c.get('source','')}`",f"**Expected micro-topics:** `{c.get('expectedMicrotopics','not specified')}`",'', '## Connected learning package','', 'Every canonical micro-topic is treated as one connected learning package:','', '**Understand → Expand → Retrieve → Reinforce → Apply**','', '| Function | Canonical pool | Learner decision |','| --- | --- | --- |','| Understand | Micro-topic | Build the mental model |','| Expand | Deep Dive | Add supported depth and distinctions |','| Retrieve | Active Recall | Reconstruct taught knowledge |','| Reinforce | Revision | Strengthen retention without introducing new facts |','| Apply | Practice | Discriminate and apply the knowledge |','', '## Canonical ownership','',f"- Syllabus/taxonomy: `{c.get('source','')}`"]
 for name in c.get('pools',[]): lines.append(f"- {name}: `{pools.get(name,{}).get('path','')}`")
 lines += ['', 'Quick Learn and Daily Learning remain supplemental learner experiences; they do not replace the canonical package.','', '## Admin content operations','', 'Admin can prepare scoped ChatGPT packets for connected package rewrites, first-time whole-unit enrichment, Quick Learn card rewrites, MCQ formatting/explanation improvements, and PYQ formatting/explanation improvements.','Every packet applies the complete standing content instructions and uses only factual resources already present in the repository. PYQ wording, option order, correct answer, year, source and identity are preserved; only whitespace formatting and explanations may be improved.','', '## Question ownership','', '`content/questions/questions.json` owns the general question bank, including authentic PYQs and general practice items.','`content/practice/practice_mcqs.json` owns package-specific original application/discrimination MCQs generated from the canonical micro-topic package.','A generated practice item must never be represented as an authentic PYQ.','', '## Verification and visibility','', '`data/verification-state.json` records epistemic review status: `AI REVIEWED` or `EXPERT VERIFIED`.','Learner visibility is not a second content-authority system; temporary owner filtering is handled locally in the Admin Workbench.','An `EXPERT VERIFIED` component is immutable to automated rewriting and must never be silently downgraded.','', '## Derived data rule','', 'The syllabus index is the only canonical taxonomy/index source. Runtime code and validation derive their mappings from it rather than maintaining parallel content indexes.','', '## Source-to-publication flow','', 'Cached extraction (source SHA-256 + extractor version) → OCR only for low-text PDF pages → page-aware source evidence → ChatGPT packet with standing instructions → manual ChatGPT generation without an API → schema/provenance checks → protection of expert-verified components → deterministic validation → human-review PR.','', 'The extraction cache is stored under `.cache/source-extraction`, excluded from Git, and persisted between workflow runs with GitHub Actions cache. Changed sources or extractor versions invalidate cached entries; missing or corrupt entries fall back to extraction.','', 'The learner runtime never calls a model or authors content. GitHub Actions prepares source-grounded packets but does not call a model API or publish generated content directly to main.','', '## Change rule','', 'When the content-pool registry or canonical package contract changes, run:','', '    python scripts/sync_documentation.py --write','', 'CI runs the same generator in check mode so architecture documentation cannot silently drift from the repository contract.','']
 return '\n'.join(lines)
def main():
 ap=argparse.ArgumentParser(); ap.add_argument('--write',action='store_true'); a=ap.parse_args(); expected=render().rstrip()+'\n'
 if a.write: DOC.parent.mkdir(parents=True,exist_ok=True); DOC.write_text(expected,encoding='utf-8'); print(f'Updated {DOC.relative_to(ROOT)}'); return 0
 if not DOC.exists(): print(f'Missing {DOC.relative_to(ROOT)}. Run with --write.',file=sys.stderr); return 1
 if DOC.read_text(encoding='utf-8').rstrip()+'\n' != expected: print('Architecture documentation is out of sync. Run: python scripts/sync_documentation.py --write',file=sys.stderr); return 1
 print('Architecture documentation is synchronized.'); return 0
if __name__=='__main__': raise SystemExit(main())
